/*
s_i = -α ((β a_i + (1-β) g_i)/(1-β^t)) / (sqrt((γ b_i + (1-γ) g_i²)/(1-γ^t)) + ε)

where

a_i ∈ ℝ
b_i ∈ ℝ
g_i ∈ ℝ
α ∈ ℝ
β ∈ ℝ
γ ∈ ℝ
ε ∈ ℝ
t ∈ ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    VectorD s;

    heartlib(
        const std::vector<double> & a,
        const std::vector<double> & b,
        const std::vector<double> & g,
        const double & α,
        const double & β,
        const double & γ,
        const double & ε,
        const double & t)
    {
        const long dim_0 = a.size();
        assert( b.size() == dim_0 );
        assert( g.size() == dim_0 );
        // s_i = -α ((β a_i + (1-β) g_i)/(1-β^t)) / (sqrt((γ b_i + (1-γ) g_i²)/(1-γ^t)) + ε)
        s.resize(dim_0);
        for( int i=1; i<=dim_0; i++){
            s[i-1] = -α * ((β * a.at(i-1) + (1 - β) * g.at(i-1)) / DT((1 - pow(β, t)))) / DT((sqrt((γ * b.at(i-1) + (1 - γ) * pow(g.at(i-1), 2)) / DT((1 - pow(γ, t)))) + ε));
        }
    }
};

