function output = heartlib(a, b, g, alpha, beta, gamma, epsilon, t)
% output = heartlib(a, b, g, α, β, γ, ε, t)
%
%    s_i = -α ((β a_i + (1-β) g_i)/(1-β^t)) / (sqrt((γ b_i + (1-γ) g_i²)/(1-γ^t)) + ε)
%    
%    where
%    
%    a_i ∈ ℝ
%    b_i ∈ ℝ
%    g_i ∈ ℝ
%    α ∈ ℝ
%    β ∈ ℝ
%    γ ∈ ℝ
%    ε ∈ ℝ
%    t ∈ ℝ
%    
    a = reshape(a,[],1);
    b = reshape(b,[],1);
    g = reshape(g,[],1);

    dim_0 = size(a, 1);
    assert( size(a,1) == dim_0 );
    assert( size(b,1) == dim_0 );
    assert( size(g,1) == dim_0 );
    assert(numel(alpha) == 1);
    assert(numel(beta) == 1);
    assert(numel(gamma) == 1);
    assert(numel(epsilon) == 1);
    assert(numel(t) == 1);

    % s_i = -α ((β a_i + (1-β) g_i)/(1-β^t)) / (sqrt((γ b_i + (1-γ) g_i²)/(1-γ^t)) + ε)

    s = zeros(dim_0,1);
    for i = 1:dim_0
        s(i) = -alpha * ((beta * a(i) + (1 - beta) * g(i)) / (1 - beta.^t)) / (sqrt((gamma * b(i) + (1 - gamma) * g(i).^2) / (1 - gamma.^t)) + epsilon);
    end
    output.s = s;
end

